import { Component } from '@angular/core';
import { ActividadEconomica } from '../../../models/actividad.economica.model';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { ActividadEconomicaService } from '../../../controllers/actividad.economica.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';

const FORM_DEF:Form=[
  {
    key:'clave',
    label:'Clave',
    type:'number',
    validator:{
      required:true,
    }
  },
  {
    key:'grupo',
    label:'Grupo',
    type:'text'
  },
  {
    key:'subgrupo',
    label:'Subgrupo',
    type:'text',
    validator:{
      required:true
    }
  },
  {
    key:'descripcion',
    label:'Descripcion',
    type:'text',
    style:{
      div:'col-12 col-sm-6 p-3'
    }
  },
  {
    key:'incluye',
    label:'Incluye',
    type:'text',
    style:{
      div:'col-12 col-sm p-3'
    }
  },
]

@Component({
    selector: 'app-form-actividades-economicas',
    imports: [GenericFormComponent],
    templateUrl: './form-actividades-economicas.component.html',
    styleUrl: './form-actividades-economicas.component.css'
})
export class FormActividadesEconomicasComponent {
  form:Form=FORM_DEF
  actividadEconomica?:ActividadEconomica

  constructor(
    public actividadEconomicaController: ActividadEconomicaService,
    private route: ActivatedRoute,
    private utils:UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async(params)=>{
      const id= this.utils.intOrNull(params.get('actividad_economica_id'))
      if(id){
        this.actividadEconomica= await this.actividadEconomicaController.find(id)
      }
    })
  }
}
